public async Task<ProductDto> GetProductAsync(int id, CancellationToken ct)
{
    var key = $"product:{id}:v2";
    return await _memory.GetOrCreateAsync(key, async entry =>
    {
        entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10);
        entry.SlidingExpiration = TimeSpan.FromMinutes(2);
        entry.Size = 1;
        return await _db.Products.AsNoTracking()
            .Where(p => p.Id == id)
            .Select(p => new ProductDto(p.Id, p.Name, p.Price))
            .FirstAsync(ct);
    }) ?? throw new NotFoundException(id);
}

public async Task<CatalogDto?> GetCatalogAsync(string tenantId, CancellationToken ct)
{
    var key = $"catalog:{tenantId}";
    var bytes = await _distributed.GetAsync(key, ct);
    if (bytes is not null)
        return JsonSerializer.Deserialize<CatalogDto>(bytes);

    var catalog = await _catalogService.BuildAsync(tenantId, ct);
    await _distributed.SetAsync(key,
        JsonSerializer.SerializeToUtf8Bytes(catalog),
        new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(15)
        }, ct);
    return catalog;
}

public async Task<DashboardDto> GetDashboardAsync(string tenantId, CancellationToken ct)
{
    var key = $"dashboard:{tenantId}";
    var cached = await _distributed.GetAsync(key, ct);
    if (cached is not null) return JsonSerializer.Deserialize<DashboardDto>(cached)!;

    var lockKey = $"lock:{key}";
    var db = _redis.GetDatabase();
    var gotLock = await db.StringSetAsync(lockKey, "1", TimeSpan.FromSeconds(30), When.NotExists);
    if (!gotLock)
    {
        await Task.Delay(50, ct);
        cached = await _distributed.GetAsync(key, ct);
        if (cached is not null) return JsonSerializer.Deserialize<DashboardDto>(cached)!;
    }

    try
    {
        var dto = await _queries.LoadDashboardAsync(tenantId, ct);
        await _distributed.SetAsync(key, JsonSerializer.SerializeToUtf8Bytes(dto),
            new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5) }, ct);
        return dto;
    }
    finally { await db.KeyDeleteAsync(lockKey); }
}

public async Task<DashboardDto> GetDashboardSafeAsync(string tenantId, CancellationToken ct)
{
    try
    {
        var bytes = await _distributed.GetAsync($"dashboard:{tenantId}", ct);
        if (bytes is not null)
            return JsonSerializer.Deserialize<DashboardDto>(bytes)!;
    }
    catch (RedisConnectionException ex)
    {
        _logger.LogWarning(ex, "Redis unavailable — bypassing L2 for {Tenant}", tenantId);
    }
    return await _queries.LoadDashboardAsync(tenantId, ct);
}
